:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8899aa;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

h1 {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 1px;
}

.score {
  font-size: 18px;
  font-weight: 600;
  color: var(--accent);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: var(--grid);
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 24px;
  text-align: center;
  border-radius: 8px;
}

.overlay.hidden {
  display: none;
}

.overlay h2 {
  font-size: 22px;
  color: var(--accent);
}

.overlay p {
  font-size: 16px;
  line-height: 1.6;
  color: var(--muted);
}

kbd {
  background: var(--bg);
  padding: 2px 8px;
  border-radius: 4px;
  font-family: inherit;
  font-size: 15px;
  border: 1px solid var(--muted);
}

.btn {
  font-family: inherit;
  font-size: 16px;
  font-weight: 600;
  padding: 12px 28px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: #ff5c7a;
}

.btn:focus-visible {
  outline: 3px solid var(--snake);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.96);
}

.controls {
  display: flex;
  gap: 12px;
}

.controls .btn {
  flex: 1;
  background: transparent;
  border: 2px solid var(--accent);
  color: var(--accent);
}

.controls .btn:hover {
  background: var(--accent);
  color: #fff;
}

.hint {
  font-size: 15px;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
    gap: 12px;
  }
  h1 {
    font-size: 20px;
  }
  .btn {
    padding: 10px 20px;
  }
}

(function () {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const gameOverEl = document.getElementById('game-over');
  const finalScoreEl = document.getElementById('final-score');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn-2');
  const restartBtn2 = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, dir, nextDir, food, score, running, paused, gameOver;
  let lastTime = 0;
  const SPEED = 140;

  function init() {
    snake = [{ x: 10, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    running = false;
    paused = true;
    gameOver = false;
    placeFood();
    updateScore();
    draw();
    overlay.classList.remove('hidden');
    gameOverEl.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  }

  function placeFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * GRID),
        y: Math.floor(Math.random() * GRID)
      };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function updateScore() {
    scoreEl.textContent = score;
  }

  function draw() {
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4ecca3' : '#3aa882';
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      endGame();
      return;
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      updateScore();
      placeFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function endGame() {
    running = false;
    gameOver = true;
    finalScoreEl.textContent = score;
    gameOverEl.classList.remove('hidden');
    overlay.classList.add('hidden');
  }

  function loop(time) {
    if (!running) return;
    if (!paused) {
      if (time - lastTime >= SPEED) {
        lastTime = time;
        step();
      }
    }
    requestAnimationFrame(loop);
  }

  function start() {
    if (gameOver) {
      init();
    }
    running = true;
    paused = false;
    overlay.classList.add('hidden');
    gameOverEl.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
    lastTime = performance.now();
    requestAnimationFrame(loop);
  }

  function togglePause() {
    if (!running || gameOver) return;
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    pauseBtn.setAttribute('aria-label', paused ? 'Resume game' : 'Pause game');
    if (!paused) {
      lastTime = performance.now();
      requestAnimationFrame(loop);
    }
  }

  function restart() {
    init();
    start();
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      if (!running && !gameOver) {
        start();
      } else {
        togglePause();
      }
      return;
    }
    if (!running || paused || gameOver) return;

    if (key === 'ArrowUp' && dir.y === 0) nextDir = { x: 0, y: -1 };
    else if (key === 'ArrowDown' && dir.y === 0) nextDir = { x: 0, y: 1 };
    else if (key === 'ArrowLeft' && dir.x === 0) nextDir = { x: -1, y: 0 };
    else if (key === 'ArrowRight' && dir.x === 0) nextDir = { x: 1, y: 0 };
  });

  startBtn.addEventListener('click', start);
  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);
  restartBtn2.addEventListener('click', restart);

  init();
})();
